// Generates every harness catalog from marketplace.config.ts and plugins.lock.json.
//
//   node scripts/build.ts            write the generated files
//   node scripts/build.ts --check    fail if anything generated is stale or inconsistent (CI)
//   --root <dir>                     repo root holding config, lock, vendor/ and outputs
//   --config <file>                  config file (default: <root>/marketplace.config.ts)
//
// Git-sourced plugins are listed at the release resolved in plugins.lock.json (ref = tag,
// sha = commit); run scripts/update.ts to refresh it. Needs Node >= 22.18. No dependencies.

import { existsSync } from 'node:fs';
import { mkdir, readdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { LOCK_FILE, pluginGitUrl, readLock } from './lock.ts';
import type { LockEntry, LockFile } from './lock.ts';
import { isVendored, readStamp, VENDOR_DIR } from './vendor.ts';
import type { MarketplaceConfig, PluginDef, PluginSource } from './types.ts';

export const REPO_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

const OPENCODE_HEADER = `// GENERATED by scripts/build.ts from marketplace.config.ts. Do not edit by hand.
// The closest thing to a "marketplace" for opencode is just an opencode config snippet
// with plugin configuration lines that an agent can pick-and-choose to add to the user's
// opencode config as requested.
`;

// ---------- small helpers ----------

type Json = Record<string, unknown>;

function compact(obj: Json): Json {
  return Object.fromEntries(Object.entries(obj).filter(([, v]) => v !== undefined));
}

function json(value: unknown): string {
  return `${JSON.stringify(value, null, 2)}\n`;
}

/** "plugins/x/" or "./plugins/x" -> "./plugins/x" */
function rel(p: string): string {
  return `./${p.replace(/^\.\//, '').replace(/\/+$/, '')}`;
}

/** The locked release, as catalog fields: ref (tag, when there is one) + sha (commit). */
function pin(e: LockEntry): Json {
  return compact({ ref: e.tag ?? undefined, sha: e.commit ?? undefined });
}

const KEBAB = /^[a-z0-9]+(?:[-.][a-z0-9]+)*$/;
const SHA = /^[0-9a-f]{40}$/;
const GH_REPO = /^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/;

// ---------- config validation ----------

export function validateConfig(cfg: MarketplaceConfig, root: string): { errors: string[]; warnings: string[] } {
  const errors: string[] = [];
  const warnings: string[] = [];
  if (!KEBAB.test(cfg.name)) errors.push(`marketplace name "${cfg.name}" must be lowercase kebab-case`);
  if (!cfg.owner?.name) errors.push('owner.name is required');

  const seen = new Set<string>();
  for (const p of cfg.plugins) {
    const where = `plugin "${p.name}"`;
    if (!KEBAB.test(p.name)) errors.push(`${where}: name must be lowercase kebab-case`);
    if (seen.has(p.name)) errors.push(`${where}: duplicate name`);
    seen.add(p.name);

    const s = p.source;
    const git = s.type === 'github' || s.type === 'git';
    if (s.type === 'github' && !GH_REPO.test(s.repo)) errors.push(`${where}: github repo must be "owner/repo"`);
    if (s.type === 'git' && !/^(https?:\/\/|git@|ssh:\/\/|file:\/\/)/.test(s.url)) errors.push(`${where}: git url must be https, ssh, git@ or file://`);
    if (git && s.sha !== undefined && !SHA.test(s.sha)) errors.push(`${where}: sha must be a full 40-character lowercase commit hash`);
    if ((git || s.type === 'local') && s.path !== undefined) {
      if (path.isAbsolute(s.path) || s.path.split('/').includes('..')) errors.push(`${where}: path must be relative with no ".."`);
    }
    if (s.type === 'local' && !existsSync(path.join(root, s.path))) errors.push(`${where}: local path ${s.path} does not exist`);
    if (p.vendor && !git) errors.push(`${where}: vendor applies only to github/git sources`);

    if (!git && s.type !== 'local' && !p.exclude?.includes('cursor')) {
      warnings.push(`${where}: not listed for Cursor (Cursor only accepts folders inside this repo)`);
    }
    if (git && !isVendored(p) && !p.exclude?.includes('cursor')) {
      warnings.push(`${where}: vendor is false, so it is not listed for Cursor`);
    }
    if (p.pi !== undefined && (p.pi === true || p.pi.source === undefined)) {
      if (s.type === 'local') errors.push(`${where}: pi needs an explicit pi.source for a local plugin`);
      if (git && s.path) errors.push(`${where}: pi cannot install a subdirectory; set pi.source explicitly`);
    }
  }
  return { errors, warnings };
}

// ---------- per-harness source shapes ----------

type GitSource = Extract<PluginSource, { type: 'github' | 'git' }>;

function claudeSource(s: PluginSource, e: LockEntry | undefined): unknown {
  if (s.type === 'local') return rel(s.path);
  if (s.type === 'npm') return compact({ source: 'npm', package: s.package, version: s.version, registry: s.registry });
  const g = s as GitSource;
  if (g.path) return { source: 'git-subdir', url: pluginGitUrl({ name: '', source: g })!, path: g.path.replace(/^\.\//, ''), ...pin(e!) };
  return g.type === 'github' ? { source: 'github', repo: g.repo, ...pin(e!) } : { source: 'url', url: g.url, ...pin(e!) };
}

function codexSource(s: PluginSource, e: LockEntry | undefined): unknown {
  if (s.type === 'local') return { source: 'local', path: rel(s.path) };
  if (s.type === 'npm') return compact({ source: 'npm', package: s.package, version: s.version, registry: s.registry });
  const url = pluginGitUrl({ name: '', source: s })!;
  if (s.path) return { source: 'git-subdir', url, path: rel(s.path), ...pin(e!) };
  return { source: 'url', url, ...pin(e!) };
}

function piSource(p: PluginDef, e: LockEntry | undefined): string | null {
  if (p.pi !== true && p.pi?.source) return p.pi.source;
  const s = p.source;
  if (s.type === 'npm') return `npm:${s.package}${s.version ? `@${s.version}` : ''}`;
  if ((s.type === 'github' || s.type === 'git') && e) {
    const host = s.type === 'github' ? `github.com/${s.repo}` : s.url.replace(/^[a-z+]+:\/\//, '').replace(/\.git$/, '');
    return `git:${host}@${e.tag ?? e.commit}`;
  }
  return null;
}

// ---------- catalog builders ----------

function included(p: PluginDef, t: 'claude' | 'codex' | 'cursor'): boolean {
  return !p.exclude?.includes(t);
}

/** A plugin is listable when it is not git-sourced, or its lock entry has a commit. */
function lockFor(p: PluginDef, lock: LockFile): { listable: boolean; entry?: LockEntry } {
  if (!pluginGitUrl(p)) return { listable: true };
  const entry = lock.plugins[p.name];
  return { listable: !!entry?.commit, entry };
}

function header(cfg: MarketplaceConfig): Json {
  return compact({
    name: cfg.name,
    owner: compact({ ...cfg.owner }),
    metadata: cfg.description ? { description: cfg.description } : undefined,
  });
}

export function buildOutputs(cfg: MarketplaceConfig, lock: LockFile): Map<string, string> {
  const out = new Map<string, string>();
  const listable = cfg.plugins
    .map((p) => ({ p, ...lockFor(p, lock) }))
    .filter((x) => x.listable);

  out.set('.claude-plugin/marketplace.json', json({
    ...header(cfg),
    plugins: listable.filter(({ p }) => included(p, 'claude')).map(({ p, entry }) => compact({
      name: p.name,
      source: claudeSource(p.source, entry),
      description: p.description,
      version: p.version,
      category: p.category,
      tags: p.tags,
      ...p.claude,
    })),
  }));

  out.set('.agents/plugins/marketplace.json', json({
    name: cfg.name,
    interface: { displayName: cfg.displayName ?? cfg.name },
    plugins: listable.filter(({ p }) => included(p, 'codex')).map(({ p, entry }) => ({
      name: p.name,
      source: codexSource(p.source, entry),
      policy: {
        installation: p.codex?.installation ?? 'AVAILABLE',
        authentication: p.codex?.authentication ?? 'ON_INSTALL',
      },
      category: p.codex?.category ?? 'Productivity',
    })),
  }));

  out.set('.cursor-plugin/marketplace.json', json({
    ...header(cfg),
    plugins: listable
      .filter(({ p }) => included(p, 'cursor') && (p.source.type === 'local' || isVendored(p)))
      .map(({ p }) => compact({
        name: p.name,
        source: p.source.type === 'local' ? rel(p.source.path) : `./${VENDOR_DIR}/${p.name}`,
        description: p.description,
        version: p.version,
        category: p.category,
        tags: p.tags,
      })),
  }));

  const opencode = cfg.plugins.filter((p) => p.opencode).map((p) => {
    const o = p.opencode!;
    const spec = `${o.package}${o.version ? `@${o.version}` : ''}`;
    return o.options ? { package: spec, options: o.options } : spec;
  });
  out.set('opencode/opencode.jsonc', OPENCODE_HEADER + json({ $schema: 'https://opencode.ai/config.json', plugins: opencode }));

  const pi = listable.filter(({ p }) => p.pi).map(({ p, entry }) => piSource(p, entry)).filter((s): s is string => s !== null);
  out.set('pi/packages.json', json({ packages: pi }));

  return out;
}

// ---------- lock / vendor consistency ----------

export async function checkConsistency(cfg: MarketplaceConfig, lock: LockFile, root: string): Promise<{ errors: string[]; warnings: string[] }> {
  const errors: string[] = [];
  const warnings: string[] = [];
  const byName = new Map(cfg.plugins.map((p) => [p.name, p]));

  for (const [name, e] of Object.entries(lock.plugins)) {
    if (!byName.has(name)) errors.push(`${name}: in ${LOCK_FILE} but not in the config`);
    else if (e.error) errors.push(`${name}: ${e.error}`);
  }
  for (const p of cfg.plugins) {
    if (!pluginGitUrl(p)) continue;
    const e = lock.plugins[p.name];
    if (!e) {
      warnings.push(`${p.name}: not in ${LOCK_FILE} yet (run node scripts/update.ts)`);
      continue;
    }
    if (isVendored(p) && e.commit) {
      const stamp = await readStamp(root, p.name);
      if (stamp?.commit !== e.commit) errors.push(`${p.name}: ${VENDOR_DIR}/${p.name} is missing or not at the locked commit`);
    }
  }
  const vendorRoot = path.join(root, VENDOR_DIR);
  if (existsSync(vendorRoot)) {
    for (const d of await readdir(vendorRoot, { withFileTypes: true })) {
      if (!d.isDirectory()) continue;
      const p = byName.get(d.name);
      if (!p || !isVendored(p)) errors.push(`${VENDOR_DIR}/${d.name}: not a vendored plugin in the config`);
    }
  }
  return { errors, warnings };
}

// ---------- CLI ----------

export async function loadConfig(configPath: string): Promise<MarketplaceConfig> {
  const mod = (await import(pathToFileURL(configPath).href)) as { default: MarketplaceConfig };
  return mod.default;
}

/** Write each generated file whose bytes changed; returns the relative paths written. */
export async function writeOutputs(root: string, outputs: Map<string, string>): Promise<string[]> {
  const written: string[] = [];
  for (const [relPath, content] of outputs) {
    const file = path.join(root, relPath);
    if (existsSync(file) && (await readFile(file, 'utf8')) === content) continue;
    await mkdir(path.dirname(file), { recursive: true });
    await writeFile(file, content);
    written.push(relPath);
  }
  return written;
}

function arg(name: string): string | undefined {
  const i = process.argv.indexOf(name);
  return i >= 0 ? process.argv[i + 1] : undefined;
}

async function main(): Promise<void> {
  const check = process.argv.includes('--check');
  const root = path.resolve(arg('--root') ?? REPO_ROOT);
  const cfg = await loadConfig(path.resolve(arg('--config') ?? path.join(root, 'marketplace.config.ts')));

  const v = validateConfig(cfg, root);
  for (const w of v.warnings) console.warn(`warning: ${w}`);
  if (v.errors.length) {
    for (const e of v.errors) console.error(`error: ${e}`);
    process.exit(1);
  }

  const lock = await readLock(root);
  const outputs = buildOutputs(cfg, lock);
  const consistency = await checkConsistency(cfg, lock, root);
  for (const w of consistency.warnings) console.warn(`warning: ${w}`);

  if (!check) {
    for (const f of await writeOutputs(root, outputs)) console.log(`wrote ${f}`);
    for (const e of consistency.errors) console.warn(`warning: ${e}`);
    console.log(`done: ${cfg.plugins.length} plugin(s)`);
    return;
  }

  const stale: string[] = [];
  for (const [relPath, content] of outputs) {
    const file = path.join(root, relPath);
    if (!existsSync(file) || (await readFile(file, 'utf8')) !== content) stale.push(relPath);
  }
  for (const e of consistency.errors) console.error(`error: ${e}`);
  if (stale.length) console.error(`stale generated files (run: node scripts/build.ts):\n  ${stale.join('\n  ')}`);
  if (stale.length || consistency.errors.length) process.exit(1);
  console.log('generated files are up to date');
}

if (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) {
  await main();
}
